%[text] # Validation - Road Grade Profile block
%[text] This script is used by unit test. After changing this script, make sure the tests continue to pass.
model_name = "HarnessModel_CustomRoadGradeProfile";
block_path = model_name + "/Road";
load_system(model_name)
sim_in = Simulink.SimulationInput(model_name);
%[text] Use "ft" for the unit of length. A 10,000-second run at 1 ft/s speed yields 10,000 ft in the curvilinear travel distance at the end of simulation.
sim_in = setModelParameter(sim_in, StopTime = "10000");
sim_in = setBlockParameter(sim_in, model_name + "/Curvilinear Speed", constant = "1");
sim_in = setBlockParameter(sim_in, model_name + "/Curvilinear Speed", constant_unit = "ft/s");  %!validation-target
expected_travel_distance_ft = 10000;
fprintf("Expected travel distance: %g\n", expected_travel_distance_ft) %[output:3376408b]
%[text] Specify -3 % road grade. Use the "linear" option for the interpolation.
% Horizontal distance for vertical profile
% Use "m" instead of "ft". This must work fine.
sim_in = setBlockParameter(sim_in, block_path, x_vector = "[ -1 0 1 ]");
sim_in = setBlockParameter(sim_in, block_path, x_vector_unit = "m");

% Road grade profile (percent) ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, grade_vector = "[ -3 -3 -3 ]");  %!validation-target

% Profile interpolation method ... !validation-target
sim_in = setBlockParameter(sim_in, block_path, profile_interp_method = "simscape.enum.interpolation.linear");
%[text] Specify non-zero initial position and elevation. Use "ft" for the unit of length.
% Initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, initial_position = "2000");  %!validation-target
sim_in = setBlockParameter(sim_in, block_path, initial_position_unit = "ft");  %!validation-target

% Elevation at initial horizontal position
sim_in = setBlockParameter(sim_in, block_path, left_elevation = "100");  %!validation-target
sim_in = setBlockParameter(sim_in, block_path, left_elevation_unit = "ft");  %!validation-target
%%
%[text] ## Run simulation
applyToModel(sim_in)
sim_out = sim(sim_in);
result = extractTimetable(sim_out.logsout);
%%
%[text] Validate the travel distance along the curvilinear surface, i.e, on the road surface. In the above simulation, the road profile was a straight slope.
z = result.("Elevation");
z_unit = result.Properties.VariableUnits{ result.Properties.VariableNames=="Elevation" };
z_ssc = simscape.Value(z, z_unit);

z0_ssc = simscape.Value( ...
  get_param(block_path, "value@left_elevation"), ...
  get_param(block_path, "left_elevation_unit") );

x = result.("Horizontal position");
x_unit = result.Properties.VariableUnits{ result.Properties.VariableNames=="Horizontal position" };
x_ssc = simscape.Value(x, x_unit);

x0_ssc = simscape.Value( ...
  get_param(block_path, "value@initial_position"), ...
  get_param(block_path, "initial_position_unit") );

% Use the same unit of length.
actual_travel_distance_ft = hypot( ...
  value(x_ssc(end), "ft") - value(x0_ssc, "ft"), ...
  value(z_ssc(end), "ft") - value(z0_ssc, "ft") );

fprintf("Actual travel distance: %g\n", actual_travel_distance_ft) %[output:5533ecf1]
absolute_difference = actual_travel_distance_ft - expected_travel_distance_ft;
fprintf("Absolute difference (actual - expected): %g\n", absolute_difference) %[output:2bba720c]
%%
%[text] Visually inspect the simulation result.
varnames = [
"Vehicle speed"
"Horizontal speed"
"Grade percent"
"Incline angle"
"Elevation"
"Horizontal position"
];

for k = 1 : numel(varnames) %[output:group:33683676]
  bevutil1.SignalUtil.plotTimedData(TimedData=result, SignalName=varnames(k), FigureHeight=150); %[output:76def285] %[output:75cc53fc] %[output:8d6b4031] %[output:7cd9c8bb] %[output:366130e8] %[output:9f397922]
end  % for %[output:group:33683676]
